  {/* USER FEEDBACK BOX (NEW) */}
  <div
    style={{
      background: "#fff",
      padding: 12,
      borderRadius: 10,
      border: "2px solid #007BFF",
      boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
    }}
  >
    <h4>User Feedback</h4>

    <button
      onClick={() => setFeedbackBox(!feedbackBox)}
      style={{
        marginTop: 8,
        padding: 8,
        width: "100%",
        borderRadius: 6,
      }}
    >
      {feedbackBox ? "Hide Feedback" : "View Feedback"}
    </button>

    {feedbackBox && (
      <div
        style={{
          marginTop: 10,
          maxHeight: 200,
          overflowY: "auto",
          paddingRight: 6,
        }}
      >
        {reports?.feedbacks?.length ? (
          reports.feedbacks.map((f, i) => (
            <div
              key={i}
              style={{
                background: "#f8f9ff",
                padding: 8,
                borderRadius: 8,
                marginBottom: 8,
              }}
            >
              <strong>{f.user_name || f.email || "User"}</strong>
              <div style={{ fontSize: 13, color: "#555", marginTop: 4 }}>
                {f.message || f.feedback || "No message"}
              </div>
              <div style={{ fontSize: 11, color: "#777", marginTop: 4 }}>
                {new Date(f.created_at).toLocaleString()}
              </div>
            </div>
          ))
        ) : (
          <p style={{ fontSize: 13, color: "#666" }}>No feedback available</p>
        )}
      </div>
    )}
  </div>
